from ledger.money import charge


class TestHalfAwayFromZero:
    """Tests for half-away-from-zero rounding behavior."""

    def test_positive_halfway_rounds_up(self):
        REQUIREMENT: Rounding is half away from zero: an amount exactly halfway between two hundredths goes to the larger magnitude. "2.675" becomes "2.68", and "-2.675" becomes "-2.68".
        assert charge("2.675") == "2.68"

    def test_negative_halfway_rounds_away_from_zero(self):
        REQUIREMENT: Rounding is half away from zero: an amount exactly halfway between two hundredths goes to the larger magnitude. "2.675" becomes "2.68", and "-2.675" becomes "-2.68".
        assert charge("-2.675") == "-2.68"

    def test_halfway_at_0_005_rounds_up(self):
        REQUIREMENT: Rounding is half away from zero: an amount exactly halfway between two hundredths goes to the larger magnitude.
        assert charge("0.005") == "0.01"

    def test_negative_halfway_at_neg_0_005_rounds_away_from_zero(self):
        REQUIREMENT: Rounding is half away from zero: an amount exactly halfway between two hundredths goes to the larger magnitude.
        assert charge("-0.005") == "-0.01"

    def test_halfway_at_1_005_rounds_up(self):
        REQUIREMENT: Rounding is half away from zero: an amount exactly halfway between two hundredths goes to the larger magnitude.
        assert charge("1.005") == "1.01"

    def test_negative_halfway_at_neg_1_005_rounds_away_from_zero(self):
        REQUIREMENT: Rounding is half away from zero: an amount exactly halfway between two hundredths goes to the larger magnitude.
        assert charge("-1.005") == "-1.01"

    def test_halfway_at_99_995_rounds_up(self):
        REQUIREMENT: Rounding is half away from zero: an amount exactly halfway between two hundredths goes to the larger magnitude.
        assert charge("99.995") == "100.00"

    def test_negative_halfway_at_neg_99_995_rounds_away_from_zero(self):
        REQUIREMENT: Rounding is half away from zero: an amount exactly halfway between two hundredths goes to the larger magnitude.
        assert charge("-99.995") == "-100.00"


class TestOutputFormat:
    """Tests for output format: exactly two decimal places."""

    def test_zero_amount_format(self):
        REQUIREMENT: returns it rounded to two decimal places, also as a string with exactly two decimals.
        assert charge("0") == "0.00"

    def test_zero_decimal_amount_format(self):
        REQUIREMENT: returns it rounded to two decimal places, also as a string with exactly two decimals.
        assert charge("0.0") == "0.00"

    def test_one_decimal_amount_format(self):
        REQUIREMENT: returns it rounded to two decimal places, also as a string with exactly two decimals.
        assert charge("1.5") == "1.50"

    def test_negative_zero_decimal_amount_format(self):
        REQUIREMENT: returns it rounded to two decimal places, also as a string with exactly two decimals.
        assert charge("-0.0") == "-0.00"

    def test_large_amount_format(self):
        REQUIREMENT: returns it rounded to two decimal places, also as a string with exactly two decimals.
        assert charge("123456789.1") == "123456789.10"

    def test_negative_large_amount_format(self):
        REQUIREMENT: returns it rounded to two decimal places, also as a string with exactly two decimals.
        assert charge("-123456789.1") == "-123456789.10"


class TestNonHalfwayValues:
    """Tests for non-halfway rounding (should still work correctly)."""

    def test_rounds_down_when_below_half(self):
        REQUIREMENT: returns it rounded to two decimal places, also as a string with exactly two decimals.
        assert charge("2.344") == "2.34"

    def test_rounds_up_when_above_half(self):
        REQUIREMENT: returns it rounded to two decimal places, also as a string with exactly two decimals.
