        assert charge("-2.344") == "-2.34"

    def test_negative_rounds_up_when_above_half(self):
        REQUIREMENT: returns it rounded to two decimal places, also as a string with exactly two decimals.
        assert charge("-2.346") == "-2.35"

    def test_already_two_decimals(self):
        REQUIREMENT: returns it rounded to two decimal places, also as a string with exactly two decimals.
        assert charge("3.14") == "3.14"

    def test_negative_already_two_decimals(self):
        REQUIREMENT: returns it rounded to two decimal places, also as a string with exactly two decimals.
        assert charge("-3.14") == "-3.14"


class TestEdgeCases:
